#include "stdlib/math/base/special/round10f.h"
#include <stdio.h>

int main( void ) {
	const float x[] = {
		-5.0f, -3.89f, -2.78f, -1.67f, -0.56f,
		0.56f, 1.67f, 2.78f, 3.89f, 5.0f
	};

	/* Round to 0.1, 1, and 10: */
	const int exps[] = { -1, 0, 1 };

	float v;
	int i;
	int j;

	for ( j = 0; j < 3; j++ ) {
		for ( i = 0; i < 10; i++ ) {
			v = stdlib_base_round10f( x[ i ], exps[ j ] );
			printf( "round10f(%f,%d) = %f\n", x[ i ], exps[ j ], v );
		}
	}
	return 0;
}
